def table(result):
 rows=['| Arm | PDS | Fidelity | Reach | Jaccard | NMAE error | Expression error ratio |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
 for a,v in result['summary'].items():rows.append('| '+a+' | '+' | '.join('missing' if v[k] is None else f'{v[k]:.6f}' for k in ('pds','fidelity','reach','jaccard','nmae','common_expression_ratio'))+' |')
 return '\n'.join(rows)

